<?php
if(!defined('ABSPATH')){exit(1);}global$wpdb;$f=get_option('cvt_custody_fixture');$assert=static function($ok,$message){if(!$ok){throw new RuntimeException($message);}};$id=absint($f['order_id']);$order=wc_get_order($id);$table=$wpdb->prefix.'cvd_order_events';
$assert('delivered'===$order->get_meta('_cvd_delivery_status',true),'flujo principal no quedó delivered');$assert('with_courier'===$order->get_meta('_cvd_operation_status',true),'operación no quedó with_courier');$assert('pending_return'===$order->get_meta('_cvd_cash_status',true),'delivered no inició pending_return');$assert(absint($f['messenger_id'])===absint($order->get_meta('_cvd_messenger_user_id',true)),'mensajero cambió');foreach(array('_cvd_handed_over_at','_cvd_to_customer_at','_cvd_delivered_at')as$key){$assert((bool)$order->get_meta($key,true),'falta timestamp '.$key);}
foreach(array('delivery:picked_up','operation:with_courier','delivery:handed_over','delivery:delivered','payment:pending_return')as$pair){list($domain,$to)=explode(':',$pair);$count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE order_id=%d AND domain=%s AND to_state=%s",$id,$domain,$to));$assert(1===$count,'evento duplicado/ausente '.$pair);}
$delivery_history=(array)$order->get_meta('_cvd_delivery_history',true);foreach(array('picked_up','handed_over','delivered')as$to){$assert(1===count(array_filter($delivery_history,static fn($e)=>$to===$e['to'])),'historial duplicado '.$to);}$operation_history=(array)$order->get_meta('_cvd_operation_history',true);$assert(1===count(array_filter($operation_history,static fn($e)=>'with_courier'===$e['to'])),'with_courier duplicado');$receipts=(array)$order->get_meta('_cvd_transition_receipts',true);foreach(array('pickup:'.$id.':integration_concurrent_pickup','custody-route','custody-delivered')as$key){$assert(isset($receipts[hash('sha256',$key)]),'falta receipt 1C.2 '.$key);}$assert('processing'===$order->get_status(),'delivered cerró WooCommerce');$assert(!in_array($order->get_meta('_cvd_cash_status',true),array('returned','verified'),true),'delivered reconcilió efectivo');$assert('pending'===$order->get_meta('_cvd_messenger_earning_status',true),'delivered aprobó ganancia');
foreach(array('failed_order_id'=>'failed','returned_order_id'=>'returned')as$key=>$target){$alt=wc_get_order(absint($f[$key]));$assert($target===$alt->get_meta('_cvd_delivery_status',true),'resultado alternativo incorrecto '.$target);$assert('processing'===$alt->get_status(),'resultado logístico cambió WooCommerce '.$target);}
$race=wc_get_order(absint($f['race_order_id']));$race_status=$race->get_meta('_cvd_delivery_status',true);$assert(in_array($race_status,array('delivered','failed'),true),'carrera sin ganador');$race_events=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$table} WHERE order_id=%d AND domain='delivery' AND to_state IN ('delivered','failed')",absint($f['race_order_id'])));$assert(1===$race_events,'dos resultados incompatibles ganaron');
$ledger_table=$wpdb->prefix.'cvd_messenger_ledger';$ledger=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$ledger_table} WHERE order_id IN (%d,%d,%d,%d)",$id,absint($f['failed_order_id']),absint($f['returned_order_id']),absint($f['race_order_id'])));$assert(0===$ledger,'1C.2 creó ledger');echo "OK: custodia 1C.2 verificada directamente en MariaDB.\n";
